with d as (select value r from jsonb_array_elements($q$[{"notes":["Use sashimi-grade or very fresh crab meat if available; tinned crab in brine works too.","White pepper, not black, keeps the soup's refined appearance, no dark specks.","Don't let the broth boil hard when pouring the egg white, or it will scramble into lumps instead of forming ribbons.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"e5c80f0f-29e0-4838-a20b-f0ad1cb10357"},{"notes":["Make the remoulade up to 3 days ahead and keep it in the fridge.","Use really good-quality roast beef sliced thin from the deli counter, it makes all the difference.","Assemble the smørrebrød just before serving so the bread stays crisp and the onions don't soften too much.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Make the remoulade: whisk together mayonnaise, Dijon mustard and wholegrain mustard until smooth. Fold in the capers and pickled gherkin. Add lemon juice and season with salt and pepper. Taste and adjust the mustard or lemon if needed."},{"text":"Lightly butter each slice of bread, spreading it all the way to the edges."},{"text":"Lay the roast beef slices on top of the butter in a slightly overlapping layer, until the bread is fully covered and the beef is soft and draped."},{"text":"Spoon remoulade generously over the beef."},{"text":"Top with pickled cucumber slices and a handful of crispy fried onions."},{"text":"Garnish with a small sprig of fresh parsley and serve immediately."}],"id":"6a54fad5-86c8-4094-8b45-8b92f42dc985"},{"notes":["The 'tarik' (pull) is what creates the signature smooth texture and foam. At home, a careful pour from height into the glass works; the mamak masters pour between two vessels for even more drama.","Use a strong black tea, English Breakfast or Assam works perfectly. The tea needs to be robust enough to stand up to the milk.","Drink it straight away while hot and foamy; it's not the same when it cools down."],"steps":[{"text":"Boil the water in a kettle or small saucepan until it reaches a rolling boil with large bubbles."},{"text":"Place the black tea leaves in a small pot or teapot. Pour the boiling water over the leaves and let steep for 2–3 minutes until the tea is very strong and dark."},{"text":"Strain the tea into a large jug, leaving behind the leaves (or remove the tea bags)."},{"text":"Pour the condensed milk and evaporated milk into two glasses or cups."},{"text":"Carefully pour the hot tea into each glass over the milk, stirring well to combine. If you're feeling brave, pour the tea from a height to create the signature foam and mix."},{"text":"Taste and add a pinch of salt if you like. Serve hot, and drink while the foam is still there."}],"id":"07746180-71bf-4e2b-9c3e-f182e0787358"},{"notes":["The pork can marinate for up to 24 hours, the longer, the better the flavour.","If you can't find achiote paste, use the annatto seed swap, or swap in 1 tbsp smoked paprika plus ½ tsp ground turmeric for a different but still delicious flavour.","Leftover cooked pork keeps in the fridge for 3 days and makes a great burrito filling.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"id":"56f5b837-093e-4de1-90df-ba4061e54da4"},{"notes":["Nopales prep: Remove the spines carefully with a sharp knife or peeler, then trim the base. If you can't find fresh nopales, jarred or tinned ones work, just drain and rinse before use, and reduce simmering time to 5–8 minutes.","This soup keeps well in the fridge for 3 days and can be frozen for up to a month."],"steps":[{"text":"Heat olive oil in a large pot over medium heat. Add the quartered onion and crushed garlic, cooking gently until softened and fragrant, about 4 minutes."},{"text":"Add the diced nopales to the pot, stirring to coat in the oil. Cook for 3–4 minutes; the nopales will release a slight mucilage, which is normal and helps thicken the broth."},{"text":"Pour in the tinned tomatoes and vegetable stock, breaking up the tomatoes gently. Bring to a simmer until the soup is bubbling gently."},{"text":"Simmer, uncovered, for 15–18 minutes until the nopales are tender and the broth has developed flavour. Taste and season with salt and black pepper."},{"text":"Ladle into bowls. Serve hot, scattered with fresh coriander and a lime wedge on the side."}],"id":"8716e77f-f36b-4296-a7c2-fed8af1249d7"},{"notes":["Make these just before serving, they're best eaten warm straight off the tawa.","Pair with sarson da saag, a dollop of yoghurt and sliced onion."],"steps":[{"text":"Mix the cornmeal, green chilli and salt in a large bowl."},{"text":"Pour in the warm water slowly, stirring with your fingers until you have a soft, sticky dough that just comes together. It should feel wetter than wheat dough, don't try to knead it smooth."},{"text":"Heat a cast iron tawa or non-stick frying pan over medium-high heat until a drop of water sizzles and disappears in a second."},{"text":"Wet your hands with water. Take a golf-ball-sized piece of dough and flatten it between your palms into a rough circle about 5 mm thick. It won't be perfect and it doesn't need to be."},{"text":"Carefully lay it on the hot tawa and cook for 1 to 2 minutes, until the bottom is pale golden and starting to blister. It will look fragile but it's not."},{"text":"Flip gently and cook the other side for another 1 to 2 minutes until golden and speckled brown. The roti will stay soft and slightly crumbly."},{"text":"Transfer to a plate and dot with a tiny bit of ghee or butter. Serve hot, while they're still warm enough to tear easily."}],"id":"c93fd96f-ebe6-46b7-9be1-08b40063f8f2"},{"notes":["Make it a day ahead; the flavour deepens as it sits.","Use sterilised jars, run them through the dishwasher on a hot cycle or boil them for 10 minutes.","Serve as a side to mezze, with fresh bread, or alongside grilled vegetables and legumes."],"id":"10623218-2acb-4a1f-bf77-60873b9ceed3"},{"notes":["Serve with steamed white rice, taro or fresh soda bread to soak up the coconut broth.","You can use any firm white fish: barramundi, snapper, flathead or basa all work well.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the oil in a large pan over medium heat. Add the onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add the garlic and stir for 1 minute until fragrant."},{"text":"Pour in the coconut milk and crushed tomatoes. Stir to combine and bring to a gentle simmer until the sauce is bubbling lightly."},{"text":"Add the silverbeet stems and cook for 3 minutes. Then add the silverbeet leaves and stir through."},{"text":"Gently add the fish chunks to the pan, stirring carefully to distribute them evenly. Simmer for 10 to 12 minutes, until the fish is cooked through and flakes easily."},{"text":"Season with salt and black pepper to taste. Serve hot with rice or taro."}],"id":"b2f82d01-347e-4774-8ff9-5f4631c3c46c"},{"notes":["Make ahead: soak the rice overnight, then steam and serve fresh.","Keep the rice warm: wrapped in a damp cloth in the bamboo basket for up to an hour.","No sticky-rice basket? A covered bamboo steamer or any covered pot works fine, just keep it warm and wrapped."],"id":"b5bb9a84-5574-4d35-8f3f-ff7a5706ef32"},{"notes":["The meringue base can be made up to 2 days ahead and kept in an airtight container.","Quandongs are tart stone fruit sourced locally in Central Australia; if unavailable outside the region, use fresh or lightly stewed stone fruit like peaches, nectarines or apricots.","Assemble just before serving so the meringue stays crisp.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"53d53b85-205c-4d06-a172-3b48a3473d58"},{"notes":["Make ahead: boil potatoes the night before and keep in the fridge. The sauce also keeps for 2 days. Warm gently and serve at room temperature.","If you can't find ají amarillo paste, look for it in the Latin or South American aisle of your supermarket, or online. It's worth seeking out, it has a distinctive mild heat and fruity flavour unique to Peruvian cooking."],"id":"6e5e84c0-d201-47fd-8df4-ceb4e61b239b"},{"steps":[{"text":"Place the sliced daikon in a large bowl. Add 1 tbsp salt and toss gently but thoroughly until every slice is coated. Set a timer: salt the radish for exactly 20 minutes, this is crucial. The radish should release its water and become pliable but still crisp."},{"text":"While the radish salts, prepare the brine: dissolve 2 tbsp salt in 1 litre of cold water in a separate bowl. Stir in the fish sauce and sugar until dissolved. Taste and adjust the salt if needed, it should taste pleasantly salty, like a good broth."},{"text":"After 20 minutes, gently rinse the radish under cold running water, pressing softly to remove excess salt and liquid. Drain well in a colander for 2 minutes."},{"text":"Transfer the drained radish to a clean container or bowl. Add the gochugaru, garlic, ginger and spring onions, tossing gently to combine."},{"text":"Pour the cold brine over the vegetables until they are just covered. Press a piece of plastic wrap or a small plate onto the surface to keep everything submerged."},{"text":"Cover and refrigerate for at least 2 hours before serving. The nabak kimchi will taste good cold from the fridge and will keep for up to 2 weeks. The flavour deepens as it ferments; after 3–4 days in the fridge, it develops a gentle fizz and tang."}],"id":"3e64a42e-12e5-4bf2-b2e4-94fdd284389a"},{"steps":[{"text":"Pour the dashi into a small pot. Add soy sauce and mirin, and bring to a simmer over medium heat until small bubbles form at the edge and the mixture is fragrant. Keep it warm."},{"text":"Cut the chilled tofu into 4 cubes, patting them dry very gently with paper towel, moisture is the enemy of crispness."},{"text":"Put cornflour in a shallow dish and season lightly with salt. Coat each tofu cube gently on all sides."},{"text":"Heat a thin layer of neutral oil in a small frying pan over medium-high heat until it shimmers. It should be hot but not smoking."},{"text":"Carefully place the tofu cubes in the oil and cook for 3 to 4 minutes, turning once, until the outside is golden and crisp all over."},{"text":"Divide the hot dashi between two bowls. Gently place two tofu cubes into each bowl."},{"text":"Top with spring onion and ginger, and serve at once, while the dashi steams and the tofu still has its gentle warmth."}],"id":"79210637-96bb-4d1f-a023-1e33dd7e52ac"},{"steps":[{"text":"Heat the oil in a heavy-bottomed pot over medium heat. Add the rice and stir constantly until it turns pale golden and smells toasted, about 3 minutes."},{"text":"Add the onion halves and bay leaf, then pour in the chicken stock. Stir once, then bring to a boil until the stock is bubbling steadily."},{"text":"Once boiling, reduce the heat to low, cover with a tight-fitting lid, and cook without lifting the lid for 15 minutes, until the rice is tender and the liquid is absorbed."},{"text":"Remove from the heat and let it rest, covered, for 2 minutes. Remove the onion halves and bay leaf, fluff the rice with a fork, season with salt to taste, and serve."}],"id":"802272b1-634e-4c7c-b697-b26a75af773f"},{"notes":["Make it a day ahead. The flavour only gets better sitting in the fridge overnight.","Serve with crusty bread, mash, or over rice to soak up the gravy.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"ab787c22-d7c2-4c9c-a9b7-13552848f549"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;